import math

def build_sparse(a={{arr}}):
    n = len(a); LOG = math.floor(math.log2(n))+1
    st = [a[:]]
    for k in range(1, LOG):
        prev = st[-1]; cur = []
        span = 1 << (k-1)
        for i in range(n - (1<<k) + 1):
            cur.append(min(prev[i], prev[i+span]))
        st.append(cur)
    return st

def query_min(st, l, r):
    k = (r-l+1).bit_length() - 1
    return min(st[k][l], st[k][r - (1<<k) + 1])
